function tallerNewId(rnd) {
  const r = rnd || Math.random;
  const h = (n) => Array.from({ length: n }, () => Math.floor(r() * 16).toString(16)).join('');
  return h(8) + '-' + h(4) + '-4' + h(3) + '-' + ['8', '9', 'a', 'b'][Math.floor(r() * 4)] + h(3) + '-' + h(12);
}

