    .sort((a, b) => (b.score == null ? -1 : b.score) - (a.score == null ? -1 : a.score) || (SR_CONF[b.confidence] || 0) - (SR_CONF[a.confidence] || 0) || String(a.title).localeCompare(String(b.title)))
