function tallerValidateAssets(assets, piece) {
  const a = Array.isArray(assets) ? assets : [];
  const errors = [];
  const re = /^[0-9a-f-]{36}\/v\d{1,3}\/[A-Za-z0-9._-]{1,80}$/;
  a.forEach((x, i) => { if (!x || !re.test(String(x.path || '')) || !String(x.path).startsWith(piece.id + '/')) errors.push('archivo ' + (i + 1) + ': ruta inválida'); });
  const kinds = a.map((x) => (x && /\.mp4$/i.test(String(x.path)) ? 'video' : 'image'));
  const f = piece.format;
  if (f === 'carrusel' && (a.length < 2 || a.length > 10 || kinds.some((k) => k !== 'image'))) errors.push('un carrusel lleva de 2 a 10 imágenes');
  if (f === 'reel' && (a.length !== 1 || kinds[0] !== 'video')) errors.push('un reel lleva un solo video MP4');
  if ((f === 'imagen' || f === 'historia') && (a.length !== 1 || kinds[0] !== 'image')) errors.push('una ' + f + ' lleva una sola imagen');
  if (f === 'texto' && a.length > 1) errors.push('un post de texto lleva como mucho una imagen');
  if (f === 'carrusel' || f === 'imagen') a.forEach((x, i) => { if (x && x.w && x.h && Math.abs(x.w / x.h - 0.8) > 0.02 && piece.channel === 'instagram') errors.push('lámina ' + (i + 1) + ': debe ser 4:5 (1080×1350)'); });
  return errors;
}

function costsView(d) {
  const hg = d.higgs && typeof d.higgs === 'object' ? d.higgs : null;
  const pieces = (d.pieces || []).filter((p) => !p.is_test && Number(p.credits_spent) > 0).sort((a, b) => Number(b.credits_spent) - Number(a.credits_spent));
  return { higgs: hg ? { balance: hg.balance == null ? null : Number(hg.balance), spent_week: Number(hg.spent_week) || 0, cap: Number(hg.cap) || 200, reserve: Number(hg.reserve) || 300, week: hg.week || null, at: hg.at || null } : null,
    pieces: pieces.slice(0, 30).map((p) => ({ id: p.id, topic: p.topic || '—', credits: Number(p.credits_spent), status: p.taller_status || p.status || null })),
    total_pieces: pieces.reduce((a, p) => a + Number(p.credits_spent), 0), note: 'Solo cuenta lo que Atacama OS gastó (registro del guardián). Tu uso en la web de Higgsfield no entra aquí, pero sí baja el saldo.' };
}

function weekView(d) {
  const tz = d.tz || 'America/Santiago';
  const now = d.now;
  const ritual = (d.ritual && wkValidateRitual(d.ritual).ok) ? d.ritual : wkDefaultRitual();
  const names = wkTasks();
  const days = wkDays(now, tz);
  const today = new Date(now).toLocaleDateString('en-CA', { timeZone: tz });
  const monday = days[0].date, friday = days[4].date;
  const nextMonday = new Date(Date.parse(monday + 'T12:00:00Z') + 7 * 86400000).toISOString().slice(0, 10);
  const inWeek = (iso) => { if (!iso) return false; const x = new Date(Date.parse(iso)).toLocaleDateString('en-CA', { timeZone: tz }); return x >= monday && x <= days[4].date; };
  const ideasNext = (d.ideas || []).filter((i) => i.week_start === nextMonday && !i.is_test);
  const proposed = ideasNext.filter((i) => ['proposed', 'changed'].includes(i.status)).length;
  const drafts = (d.messages || []).filter((m) => m.direction === 'outbound' && m.status === 'draft').length;
  const pieces = (d.pieces || []).filter((p) => !p.is_test && p.taller_status);
  const toReview = pieces.filter((p) => p.taller_status === 'para_revisar').length;
  const closing = pieces.filter((p) => p.needs_by && inWeek(p.needs_by) && p.taller_status !== 'descartada');
  const scheduled = closing.filter((p) => ['programada', 'programada_pendiente_de_clic', 'publicada'].includes(p.taller_status)).length;
  const meetings = (d.meetings || []).filter((m) => m.meeting_start).map((m) => ({ at: m.meeting_start, day: new Date(Date.parse(m.meeting_start)).toLocaleDateString('en-CA', { timeZone: tz }), who: [m.name, m.company].filter(Boolean).join(' · ') || 'Reunión' }));
  const intelThisWeek = Boolean(d.intel_at && inWeek(d.intel_at));
  const light = closing.length === 0 ? 'sin_datos' : scheduled === closing.length ? 'verde' : scheduled >= Math.ceil(closing.length * 0.6) ? 'amarillo' : 'rojo';
  const task = (id, date) => {
    if (id === 'ideas') return { id, label: names[id] + ' (' + nextMonday + ')', done: ideasNext.length > 0 && proposed === 0, detail: ideasNext.length ? (proposed ? proposed + ' por decidir' : 'todas decididas') : 'aún no llega la propuesta', href: '/ops?view=ideas' };
    if (id === 'correos') return { id, label: names[id], done: drafts === 0, detail: drafts ? drafts + ' borradores esperando' : 'sin borradores', href: '/ops?view=aprobaciones&filter=correos' };
    if (id === 'reuniones') { const m = meetings.filter((x) => x.day === date); return { id, label: names[id], done: date < today, detail: m.length ? m.length + (m.length === 1 ? ' reunión' : ' reuniones') : 'sin reuniones agendadas', href: null, meetings: m }; }
    if (id === 'competencia') return { id, label: names[id], done: intelThisWeek, detail: intelThisWeek ? 'informe listo esta semana' : 'aún no llega el informe de esta semana', href: '/ops?view=contenido' };
    if (id === 'revisar_piezas') return { id, label: names[id], done: toReview === 0, detail: toReview ? toReview + ' para revisar' : 'nada pendiente', href: '/ops?view=taller' };
    if (id === 'cierre') return { id, label: names[id] + ' ' + scheduled + ' de ' + closing.length, done: closing.length > 0 && scheduled === closing.length, detail: light === 'verde' ? 'lista' : light === 'sin_datos' ? 'sin piezas con cierre esta semana' : (closing.length - scheduled) + ' por programar', href: '/ops?view=taller', light };
    return { id, label: id, done: false, detail: '', href: null };
  };
  const out = days.map((x) => ({ key: x.key, label: { lun: 'Lunes', mar: 'Martes', mie: 'Miércoles', jue: 'Jueves', vie: 'Viernes' }[x.key], date: x.date, today: x.date === today, tasks: (ritual[x.key] || []).map((t) => task(t, x.date)) }));
  const all = out.flatMap((x) => x.tasks);
  return { generated_at: new Date(now).toISOString(), week: monday, friday, ritual, days: out, progress: { done: all.filter((t) => t.done).length, total: all.length },
    meetings_today: meetings.filter((m) => m.day === today), close: { scheduled, total: closing.length, light } };
}

function wkDays(ms, tz) {
  const ymd = (t) => new Date(t).toLocaleDateString('en-CA', { timeZone: tz });
  const wd = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'short' }).format(new Date(ms)));
  const mondayMs = ms - ((wd + 6) % 7) * 86400000;
  return ['lun', 'mar', 'mie', 'jue', 'vie'].map((k, i) => ({ key: k, date: ymd(mondayMs + i * 86400000) }));
}

function wkDefaultRitual() {
  return { lun: ['ideas', 'correos'], mar: ['reuniones'], mie: ['competencia'], jue: ['revisar_piezas'], vie: ['cierre'] };
}

function wkTasks() {
  return { ideas: 'Decidir las ideas de la semana', correos: 'Revisar los borradores de correo', reuniones: 'Reuniones del día', competencia: 'Leer el informe de competencia', revisar_piezas: 'Revisar piezas del Taller', cierre: 'Cierre: semana siguiente programada' };
}

function wkValidateRitual(r) {
  const days = ['lun', 'mar', 'mie', 'jue', 'vie'];
  const known = Object.keys(wkTasks());
  if (!r || typeof r !== 'object') return { ok: false, message: 'Ritual inválido.' };
  const out = {}, seen = new Set();
  for (const d of days) {
    const list = Array.isArray(r[d]) ? r[d] : [];
    if (list.length > 4) return { ok: false, message: 'Máximo 4 tareas por día.' };
    for (const t of list) {
      if (!known.includes(t)) return { ok: false, message: 'Tarea desconocida: ' + t };
      if (seen.has(t)) return { ok: false, message: 'La tarea «' + wkTasks()[t] + '» está en dos días.' };
      seen.add(t);
    }
    out[d] = list.slice();
  }
  return { ok: true, value: out };
}

function lnContext({ events, proposals, min, enabled, paused, with_test }) {
  const m = Number(min) > 0 ? Number(min) : 30;
  const pats = lnPatterns(events, m, with_test);
  const real = (events || []).filter((e) => with_test || !e.is_test);
  const by_type = {};
  real.forEach((e) => { by_type[e.type] = (by_type[e.type] || 0) + 1; });
  const open = (proposals || []).filter((p) => p.status === 'proposed' && !p.is_test);
  const mode = paused ? 'skip' : !enabled ? 'skip' : 'run';
  return {
    ok: true, mode, reason: paused ? 'pausa general activa' : !enabled ? 'job de aprendizaje apagado (content_config.learning_enabled = false)' : pats.some((p) => p.sufficient) ? 'hay patrones con muestra suficiente' : 'muestra insuficiente en todos los patrones',
    min_sample: m, total_events: real.length, by_type,
    patterns: pats.slice(0, 40).map(({ ids, ...p }) => p),
    open_patterns: open.map((p) => ((p.evidence || []).find((x) => x && x.type === 'pattern') || {}).id).filter(Boolean),
    rules: 'Solo propones; nunca aplicas. Cada propuesta cita ≥ 3 eventos del patrón (event_id) y un patrón con muestra suficiente; con menos se responde «muestra insuficiente».',
  };
}

function lnDecidePlan(req, prop, { now, by }) {
  if (!prop) return { error: 'propuesta_no_encontrada', message: 'No encontré esa propuesta.' };
  if (prop.is_test && req.test !== true) return { error: 'propuesta_test', message: 'Esa propuesta es de prueba.' };
  if (prop.status !== 'proposed') return { error: 'ya_decidida', message: 'Esa propuesta ya estaba ' + (prop.status === 'approved' ? 'aprobada' : 'rechazada') + '.' };
  const st = req.decision === 'approve' ? 'approved' : 'rejected';
  return {
    resp: { ok: true, status: st, message: st === 'approved' ? 'Aprobada. No se aplica sola: el cambio se hace con tu orden (Claude Code o Hermes) y queda en el historial.' : 'Rechazada. El job no la volverá a proponer igual.' },
    writes: [{ method: 'PATCH', path: 'learning_proposals?id=eq.' + prop.id + '&status=eq.proposed', body: { status: st, decided_at: new Date(now).toISOString(), decided_by: by }, prefer: 'return=representation', check_rows: true, check_message: 'La propuesta cambió mientras decidías. Recarga.' }],
  };
}

function lnEventKeys(e) {
  const b = e.before || {}, a = e.after || {}, keys = [];
  if (e.type === 'email_edit') {
    const wb = String(b.body || '').split(/\s+/).filter(Boolean).length, wa = String(a.body || '').split(/\s+/).filter(Boolean).length;
    if (wb && wa < wb * 0.85) keys.push(['playbook', 'acorta', 'Christian acorta el correo (−15 % o más)']);
    if (wb && wa > wb * 1.15) keys.push(['playbook', 'alarga', 'Christian alarga el correo (+15 % o más)']);
    const lb = lnLines(b.body), la = lnLines(a.body);
    if (lb[0] && la[0] && lb[0] !== la[0]) keys.push(['playbook', 'saludo', 'Christian cambia el saludo']);
    if (lb.length && la.length && lb[lb.length - 1] !== la[la.length - 1]) keys.push(['playbook', 'cierre', 'Christian cambia el cierre']);
    if (String(b.subject || '').trim() && String(b.subject || '').trim() !== String(a.subject || '').trim()) keys.push(['evaluador', 'asunto', 'Christian cambia el asunto']);
    const after = new Set(lnWords(a.body + ' ' + a.subject));
    [...new Set(lnWords(b.body + ' ' + b.subject))].filter((w) => !after.has(w)).forEach((w) => keys.push(['evaluador', 'quita:' + w, 'Christian quita la palabra «' + w + '»']));
  } else if (e.type === 'idea_discard') {
    if (b.format) keys.push(['ranking', 'descarta_formato:' + b.format, 'Descarta ideas de formato ' + b.format]);
    if (b.channel) keys.push(['ranking', 'descarta_red:' + b.channel, 'Descarta ideas de ' + b.channel]);
    [...new Set(lnWords(e.reason))].forEach((w) => keys.push(['ranking', 'motivo:' + w, 'Motivo de descarte con «' + w + '»']));
  } else if (e.type === 'piece_feedback') {
    [...new Set(lnWords((a && a.text) || e.reason))].forEach((w) => keys.push(['receta', 'pide:' + w, 'Pide cambios con «' + w + '»']));
  } else if (e.type === 'piece_ok') {
    keys.push(['receta', 'ok_formato:' + (b.format || 'pieza'), 'Programa sin cambios piezas de formato ' + (b.format || '—')]);
  }
  return keys;
}

function lnLines(s) { return String(s || '').split(/\n+/).map((x) => x.trim()).filter(Boolean); }

function lnPatterns(events, min, withTest) {
  const m = Number(min) > 0 ? Number(min) : 30, by = {};
  (events || []).filter((e) => e && (withTest || !e.is_test)).forEach((e) => {
    lnEventKeys(e).forEach(([target, key, label]) => {
      const id = target + ':' + key;
      const p = by[id] || (by[id] = { id, target, key, label, n: 0, ids: [], examples: [] });
      p.n++; p.ids.push(e.id);
      if (p.examples.length < 6) p.examples.push({ event_id: e.id, subject_id: e.subject_id || null, at: e.created_at || null, type: e.type });
    });
  });
  return Object.values(by).map((p) => ({ ...p, sufficient: p.n >= m })).sort((x, y) => y.n - x.n || x.id.localeCompare(y.id));
}

function lnProposePlan(list, { events, proposals, min, now, is_test }) {
  const m = Number(min) > 0 ? Number(min) : 30;
  const pats = Object.fromEntries(lnPatterns(events, m, is_test).map((p) => [p.id, p]));
  const open = new Set((proposals || []).filter((p) => p.status === 'proposed' && !!p.is_test === !!is_test).map((p) => ((p.evidence || []).find((x) => x && x.type === 'pattern') || {}).id));
  if (!Array.isArray(list) || !list.length) return { error: 'sin_propuestas', message: 'No llegaron propuestas.' };
  if (list.length > 8) return { error: 'demasiadas', message: 'Máximo 8 propuestas por semana.' };
  const writes = [], discarded = [];
  list.forEach((x, i) => {
    const p = pats[String((x && x.pattern_id) || '')];
    const text = String((x && x.proposal) || '').trim();
    const cites = Array.isArray(x && x.citations) ? x.citations.filter((c) => c && p && p.ids.includes(c.event_id)) : [];
    const why = !p ? 'patrón desconocido' : !lnTargets().includes(p.target) ? 'destino inválido' : !p.sufficient ? 'muestra insuficiente (' + p.n + ' de ' + m + ')' : text.length < 30 || text.length > 1500 ? 'propuesta de 30–1500 caracteres' : cites.length < 3 ? 'faltan ≥ 3 citas de eventos del patrón' : open.has(p.id) ? 'ya hay una propuesta abierta para ese patrón' : null;
    if (why) { discarded.push({ i, pattern_id: (x && x.pattern_id) || null, why }); return; }
    open.add(p.id);
    writes.push({ method: 'POST', path: 'learning_proposals', prefer: 'return=minimal', body: { target: p.target, proposal: text, sample_size: p.n, is_test: !!is_test, created_at: new Date(now).toISOString(),
      evidence: [{ type: 'pattern', id: p.id, label: p.label, n: p.n }].concat(cites.slice(0, 10).map((c) => ({ type: 'event', id: c.event_id, note: String(c.note || '').slice(0, 300) }))) } });
  });
  return { resp: { ok: true, proposed: writes.length, discarded, text: writes.length + ' propuesta(s) guardada(s) para que Christian decida' + (discarded.length ? '; ' + discarded.length + ' descartada(s)' : '') + '. Nada se aplicó.' }, writes };
}

function lnTargets() { return ['playbook', 'evaluador', 'ranking', 'receta']; }

function lnView({ events, proposals, min }) {
  const c = lnContext({ events, proposals, min, enabled: true, paused: false });
  const list = (proposals || []).filter((p) => !p.is_test).sort((a, b) => (a.status === 'proposed' ? 0 : 1) - (b.status === 'proposed' ? 0 : 1) || String(b.created_at).localeCompare(String(a.created_at))).slice(0, 30)
    .map((p) => ({ id: p.id, target: p.target, proposal: p.proposal, sample_size: p.sample_size, status: p.status, decided_at: p.decided_at || null, created_at: p.created_at,
      pattern: ((p.evidence || []).find((x) => x && x.type === 'pattern') || {}).label || null, citations: (p.evidence || []).filter((x) => x && x.type === 'event').length }));
  return { min_sample: c.min_sample, total_events: c.total_events, by_type: c.by_type, patterns: c.patterns.slice(0, 12), sufficient: c.patterns.filter((p) => p.sufficient).length, proposals: list };
}

function lnWords(s) {
  const STOP = 'para,como,este,esta,estos,estas,pero,porque,donde,cuando,sobre,entre,desde,hasta,también,tiene,tienen,puede,pueden,hacer,usted,ustedes,nuestro,nuestra,ellos,ellas,mucho,muchos,cada,todo,todos,otra,otro,algo,solo,más,menos,muy,bien,están,estamos,quiero,saludos,estimado,estimada,atacama,labs'.split(',');
  return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').match(/[a-zñ]{5,}/g)?.filter((w) => !STOP.includes(w)) || [];
}

function resultsView({ now, pieces, resources, attributions, leads, metrics, versions, feedback, days }) {
  const D = Number(days) > 0 ? Number(days) : 60, since = now - D * 86400000;
  const real = (pieces || []).filter((p) => p && !p.is_test);
  const res = Object.fromEntries((resources || []).map((r) => [r.id, r]));
  const resBySlug = Object.fromEntries((resources || []).map((r) => [r.slug, r]));
  const att = (attributions || []).filter((a) => !a.is_test);
  const web = (leads || []).filter((l) => l.source_section === 'recurso-cierre' && rsSlugOf(l.source_page));
  const lastMetric = {};
  (metrics || []).forEach((m) => { const k = m.content_piece_id, rank = { '24h': 1, '72h': 2, '7d': 3 }[m.metric_window] || 0; if (!lastMetric[k] || rank > lastMetric[k].rank) lastMetric[k] = { rank, likes: m.likes, comments: m.comments, shares: m.shares, window: m.metric_window }; });
  const at = (p) => p.published_at || p.scheduled_at || p.created_at;
  const shown = real.filter((p) => Date.parse(at(p)) >= since && (p.published_at || ['programada', 'publicada'].includes(p.taller_status) || att.some((a) => a.piece_id === p.id)));
  const piecesOut = shown.map((p) => {
    const r = p.resource_id ? res[p.resource_id] : null;
    const dm = att.filter((a) => a.piece_id === p.id);
    const w = r ? web.filter((l) => rsSlugOf(l.source_page) === r.slug && Date.parse(l.created_at) >= Date.parse(at(p))) : [];
    const mt = lastMetric[p.id] || null;
    return { id: p.id, topic: p.topic || '(sin título)', channel: p.channel || null, format: p.format || null, at: at(p), keyword: p.keyword || (p.idea && p.idea.keyword) || null,
      resource: r ? { slug: r.slug, name: r.name } : null, contacts_dm: dm.length, contacts_web: w.length, meetings: w.filter((l) => l.meeting_start).length,
      metrics: mt ? { likes: mt.likes, comments: mt.comments, shares: mt.shares, window: mt.window } : null };
  }).sort((a, b) => String(b.at).localeCompare(String(a.at)));
  const resOut = (resources || []).filter((r) => r.status === 'active' || web.some((l) => rsSlugOf(l.source_page) === r.slug)).map((r) => {
    const w = web.filter((l) => rsSlugOf(l.source_page) === r.slug && Date.parse(l.created_at) >= since);
    const pcs = real.filter((p) => p.resource_id === r.id).map((p) => p.id);
    return { slug: r.slug, name: r.name, web_leads: w.length, meetings: w.filter((l) => l.meeting_start).length, contacts_dm: att.filter((a) => a.resource_id === r.id || pcs.includes(a.piece_id)).length, pieces: pcs.length };
  }).sort((a, b) => b.web_leads + b.contacts_dm - (a.web_leads + a.contacts_dm) || a.slug.localeCompare(b.slug));
  const unknownWeb = web.filter((l) => !resBySlug[rsSlugOf(l.source_page)]).length;
  return { generated_at: new Date(now).toISOString(), days: D, pieces: piecesOut, resources: resOut, unknown_web: unknownWeb, summary: rsMondaySummary({ now, pieces: real, attributions: att, leads: web, resources }),
    iterations: rsIterations({ pieces: real, versions, feedback }).slice(0, 30),
    note: 'Atribución parcial: los comentarios y mensajes de Instagram no se leen solos. Registra cada contacto con «Registrar contacto de esta pieza». Oportunidades y ganados se ven en GHL.' };
}

function rsIterations({ pieces, versions, feedback }) {
  return (pieces || []).filter((p) => (versions || []).some((v) => v.piece_id === p.id)).map((p) => {
    const vs = (versions || []).filter((v) => v.piece_id === p.id && !v.is_test).sort((a, b) => a.version_no - b.version_no);
    const fb = (feedback || []).filter((f) => f.piece_id === p.id && !f.is_test);
    const first = vs[0] ? Date.parse(vs[0].created_at) : null, last = vs.length ? Date.parse(vs[vs.length - 1].created_at) : null;
    return { id: p.id, topic: p.topic || '(sin título)', format: p.format || null, status: p.taller_status || null, versions: vs.length, feedback: fb.length,
      credits: Math.round(vs.reduce((s, v) => s + Number(v.cost_credits || 0), 0) * 100) / 100, days: first && last ? Math.round(((last - first) / 86400000) * 10) / 10 : 0, first_try: vs.length === 1 && fb.length === 0 };
  }).sort((a, b) => b.versions - a.versions || b.feedback - a.feedback);
}

function rsMondaySummary({ now, pieces, attributions, leads, resources }) {
  const d = new Date(now), dow = (d.getUTCDay() + 6) % 7;
  const mon = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) - (dow + 7) * 86400000, end = mon + 7 * 86400000;
  const inW = (t) => { const x = Date.parse(t); return x >= mon && x < end; };
  const byRes = Object.fromEntries((resources || []).map((r) => [r.id, r]));
  const lines = [];
  (pieces || []).forEach((p) => {
    const dm = (attributions || []).filter((a) => a.piece_id === p.id && inW(a.created_at)).length;
    const r = p.resource_id ? byRes[p.resource_id] : null;
    const w = r ? (leads || []).filter((l) => rsSlugOf(l.source_page) === r.slug && inW(l.created_at)) : [];
    const contacts = dm + w.length, meet = w.filter((l) => l.meeting_start).length;
    if (contacts || meet) lines.push({ piece_id: p.id, contacts, meetings: meet, text: '«' + String(p.topic || 'pieza').slice(0, 60) + '» trajo ' + contacts + (contacts === 1 ? ' contacto' : ' contactos') + (meet ? ' y ' + meet + (meet === 1 ? ' reunión' : ' reuniones') : '') + '.' });
  });
  lines.sort((a, b) => b.contacts + b.meetings * 3 - (a.contacts + a.meetings * 3));
  return { week: new Date(mon).toISOString().slice(0, 10), lines: lines.slice(0, 8), empty_text: lines.length ? null : 'La semana pasada ninguna pieza registró contactos (atribución parcial: faltan los contactos sin registrar).' };
}

function rsPieceContactInput(req) {
  const name = String(req.contact_name || '').trim(), handle = String(req.handle || '').trim().replace(/^@/, ''), kw = String(req.keyword || '').trim().toLowerCase();
  if (!/^[0-9a-f-]{36}$/i.test(String(req.piece_id || ''))) return { error: 'falta_pieza', message: 'piece_id inválido.' };
  if (name.length < 2 || name.length > 80) return { error: 'falta_nombre', message: 'Escribe el nombre (2–80 caracteres).' };
  if (handle && !/^[A-Za-z0-9._]{1,30}$/.test(handle)) return { error: 'usuario_invalido', message: 'El usuario de Instagram solo lleva letras, números, punto y guion bajo.' };
  if (kw && !/^[a-z0-9ñáéíóú-]{2,30}$/.test(kw)) return { error: 'palabra_invalida', message: 'La palabra clave va en una sola palabra (2–30 letras).' };
  return { ok: true, name, handle: handle || null, keyword: kw || null };
}

function rsSlugOf(page) {
  const m = String(page || '').match(/\/recursos\/([a-z0-9]+(?:-[a-z0-9]+)*)/);
  return m ? m[1] : null;
}

function srAttention(input, now) {
  const inp = input || {};
  const SR_TAB = { production: 'radar_produccion', product: 'radar_productos', partner: 'radar_alianzas', event: 'radar_eventos' };
  const max = Math.max(0, Math.min(3, inp.daily_max_items == null ? 3 : Number(inp.daily_max_items)));
  const out = [], seen = new Set();
  const push = (x) => { const k = x.class + ':' + x.id; if (!seen.has(k)) { seen.add(k); out.push(x); } };
  for (const t of Array.isArray(inp.targets) ? inp.targets : []) {
    if (!t || t.is_test || t.status !== 'confirmed' || t.monitor_enabled !== true) continue;
    const h = srProductionHealth(t.checks, now, t.alert_open);
    if (!h.confirmed_down) continue;
    push({ rank: 0, sub: 0, class: 'production', id: t.id, title: t.logical_name, what: t.logical_name + ' no responde', why: 'Dos comprobaciones seguidas fallaron (HTTP).', action: 'Revisar el servicio', tab: SR_TAB.production });
  }
  const opps = (Array.isArray(inp.opportunities) ? inp.opportunities : []).filter((o) => o && !o.is_test);
  for (const o of opps) {
    if ((o.kind !== 'event' && o.kind !== 'partner') || !['new', 'shortlisted'].includes(o.status) || o.last_daily_at || o.confidence === 'low' || !(o.score >= 75)) continue;
    const left = srDaysLeft(o.deadline_at, now);
    if (left === null || left < 0 || left > 14) continue;
    push({ rank: left <= 7 ? 1 : 2, sub: left, class: o.kind, id: o.id, title: o.title, what: o.title, why: 'Plazo confirmado en ' + left + (left === 1 ? ' día' : ' días') + ' · puntaje ' + o.score, action: o.next_action, tab: SR_TAB[o.kind] });
  }
  const prods = opps.filter((o) => o.kind === 'product' && o.status === 'new' && !o.last_daily_at && o.score >= 80 && o.license_verified === true && !!o.license_id && o.coverage_pct >= 90 && !(o.score_parts && o.score_parts.coverage_provisional) && !(Array.isArray(o.critical_blockers) && o.critical_blockers.length)).sort((a, b) => b.score - a.score);
  if (prods[0]) { const o = prods[0]; push({ rank: 3, sub: 0, class: 'product', id: o.id, title: o.title, what: o.title, why: 'Licencia verificada · cobertura auditada ' + o.coverage_pct + '% · puntaje ' + o.score, action: o.next_action, tab: SR_TAB.product }); }
  out.sort((a, b) => a.rank - b.rank || a.sub - b.sub);
  return out.slice(0, max);
}

function srCanonicalUrl(input) {
  const raw = srStr(input);
  if (!raw || raw.length > 2000) return null;
  let u;
  try { u = new URL(raw); } catch { return null; }
  if (u.protocol !== 'https:') return null;
  if (u.username || u.password) return null;
  if (u.port && u.port !== '443') return null;
  const host = u.hostname.toLowerCase().replace(/\.$/, '');
  if (srIsPrivateHost(host)) return null;
  let path = u.pathname || '/';
  if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
  const keyOf = (p) => { const k = p.split('=')[0].replace(/\+/g, ' '); try { return decodeURIComponent(k).trim(); } catch { return k.trim(); } };
  const pairs = u.search.replace(/^\?/, '').split('&').filter(Boolean).filter((p) => !/^(utm_.*|fbclid|gclid|igshid)$/i.test(keyOf(p)));
  pairs.sort((a, b) => { const [ka, va = ''] = a.split('='); const [kb, vb = ''] = b.split('='); return ka < kb ? -1 : ka > kb ? 1 : va < vb ? -1 : va > vb ? 1 : 0; });
  return 'https://' + host + path + (pairs.length ? '?' + pairs.join('&') : '');
}

function srCheckPlan(p, ctx) {
  const x = p && typeof p === 'object' ? p : {}, c = ctx || {};
  const g = srMonitorGuard(c);
  if (g) return g;
  const now = c.now == null ? Date.now() : c.now, test = x.test === true;
  if (!srIsUuid(x.target_id)) return { error: 'target_id_invalido', message: 'target_id (uuid del servicio) es obligatorio.' };
  const t = c.target;
  if (!t) return { error: 'target_no_encontrado', message: 'No encontré ese servicio.' };
  if ((t.is_test === true) !== test) return { error: 'registro_test', message: t.is_test === true ? 'Ese servicio es de prueba: un chequeo real no lo modifica.' : 'Ese servicio es real: una prueba no lo modifica.' };
  if (t.status !== 'confirmed' || t.monitor_enabled !== true) return { error: 'target_no_monitoreado', message: 'Ese servicio no está confirmado con el monitoreo encendido: no se registra.' };
  if (['healthy', 'degraded', 'down', 'unknown'].indexOf(x.result) < 0) return { error: 'resultado_invalido', message: 'result: healthy | degraded | down | unknown.' };
  const st = x.http_status == null ? null : Number(x.http_status);
  if (st !== null && !(Number.isInteger(st) && st >= 100 && st <= 599)) return { error: 'http_invalido', message: 'http_status debe estar entre 100 y 599.' };
  const lat = x.latency_ms == null ? null : Number(x.latency_ms);
  if (lat !== null && !(Number.isInteger(lat) && lat >= 0 && lat <= 120000)) return { error: 'latencia_invalida', message: 'latency_ms debe estar entre 0 y 120000.' };
  const code = x.error_code == null || x.error_code === '' ? null : String(x.error_code);
  if (code !== null && !/^[A-Za-z0-9_.:-]{1,60}$/.test(code)) return { error: 'codigo_invalido', message: 'error_code: hasta 60 caracteres simples.' };
  const sha = x.observed_sha == null || x.observed_sha === '' ? null : String(x.observed_sha);
